+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details.is-open {
+      grid-template-rows: 1fr;
+    }
+
+    .details-inner {
+      overflow: hidden;
+    }
+
+    .details p {
+      margin: 0;
+      padding: 0 22px 22px;
+      color: var(--muted);
+      line-height: 1.7;
+    }
+
